begin read only; set local search_path=''; select jsonb_build_object('spec',(select jsonb_build_object(
'functions',(select coalesce(jsonb_object_agg(n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')',jsonb_build_object('sha256',encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex'),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'securityDefiner',p.prosecdef,'config',p.proconfig)),'{}') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where exists(select 1 from(values ('private','performance_review_actor'),('private','performance_review_identity'),('private','performance_review_candidate'),('private','performance_review_date'),('private','performance_review_lock_people'),('private','performance_review_audience'),('private','performance_review_project'),('public','performance_review_workspace'),('public','start_performance_review'),('private','performance_review_closed'),('private','performance_review_text'),('private','performance_review_nonblank'),('private','performance_review_answers'),('private','performance_review_manager_input'),('private','performance_review_meeting_end'),('private','performance_review_document'),('private','performance_review_meeting_ended'),('public','mutate_performance_review'),('public','get_performance_review_document'),('public','get_performance_review_operation'),('public','claim_performance_review_mail'),('public','begin_performance_review_mail'),('public','finish_performance_review_mail')) f(schema_name,function_name) where n.nspname=f.schema_name and p.proname=f.function_name)),
'relations',(select jsonb_object_agg(target,(select jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'forced',c.relforcerowsecurity,'kind',c.relkind,'persistence',c.relpersistence,'options',c.reloptions,'replicaIdentity',c.relreplident,'accessMethod',(select amname from pg_am where oid=c.relam),
'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'acl',a.attacl::text,'identity',a.attidentity,'generated',a.attgenerated,'storage',a.attstorage,'default',pg_get_expr(d.adbin,d.adrelid)) order by a.attnum) from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),
'constraints',(select jsonb_agg(jsonb_build_object('name',k.conname,'definition',pg_get_constraintdef(k.oid)) order by k.conname) from pg_constraint k where k.conrelid=c.oid),
'indexes',(select jsonb_agg(pg_get_indexdef(i.indexrelid) order by pg_get_indexdef(i.indexrelid)) from pg_index i where i.indrelid=c.oid),
'policies',(select jsonb_agg(to_jsonb(p) order by p.polname) from pg_policy p where p.polrelid=c.oid),
'fkTriggers',(select jsonb_agg(jsonb_build_object('relation',t.tgrelid::regclass::text,'function',t.tgfoid::regprocedure::text,'type',t.tgtype,'enabled',t.tgenabled,'constraint',pg_get_constraintdef(t.tgconstraint),'internal',t.tgisinternal,'deferrable',t.tgdeferrable,'initiallyDeferred',t.tginitdeferred,'arguments',encode(t.tgargs,'hex'),'name',portable.name,'definition',case when portable.name<>t.tgname then overlay(pg_get_triggerdef(t.oid) placing quote_ident(portable.name) from length('CREATE CONSTRAINT TRIGGER ')+1 for length(quote_ident(t.tgname))) else pg_get_triggerdef(t.oid) end,'when',pg_get_expr(t.tgqual,t.tgrelid),'updateColumns',t.tgattr::text,'argumentCount',t.tgnargs,'constraintName',k.conname,'constraintRelation',nullif(t.tgconstrrelid,0)::regclass::text,'constraintIndex',nullif(t.tgconstrindid,0)::regclass::text,'parent',t.tgparentid::text,'oldTable',t.tgoldtable,'newTable',t.tgnewtable) order by t.tgrelid::regclass::text,t.tgfoid::regprocedure::text,k.conname,portable.name) from pg_trigger t left join pg_constraint k on k.oid=t.tgconstraint cross join lateral (select case when t.tgisinternal and k.contype='f' and t.tgname=('RI_ConstraintTrigger_'||case when t.tgrelid=k.conrelid then 'c' else 'a' end||'_'||t.oid::text) then 'RI_ConstraintTrigger_'||case when t.tgrelid=k.conrelid then 'c' else 'a' end||'_<oid>' else t.tgname::text end as name) portable where t.tgrelid=c.oid or t.tgconstraint in (select k.oid from pg_constraint k where k.conrelid=c.oid))) from pg_class c where c.oid=to_regclass(target))) from unnest(array['private.performance_reviews','private.performance_review_events','private.performance_review_operations','private.performance_review_mail_outbox']::text[]) target),
'sequences',(select jsonb_object_agg(target,(select jsonb_build_object('owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'parameters',to_jsonb(s)-'seqrelid') from pg_class c join pg_sequence s on s.seqrelid=c.oid where c.oid=to_regclass(target))) from unnest(array['private.performance_reviews_review_no_seq','private.performance_review_events_id_seq']::text[]) target))),'anchors',(select jsonb_object_agg(signature,jsonb_build_object('sha256',encode(extensions.digest(pg_get_functiondef(p.oid),'sha256'),'hex'),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'securityDefiner',p.prosecdef,'config',p.proconfig)) from unnest(array['private.portal_role_policy(uuid)','private.lock_portal_role_actor()','private.resolve_internal_org_employee_manager(uuid)','private.reject_retired_test_identity_reference()','private.confirmed_test_purge_schema_hash()']::text[]) signature left join pg_proc p on p.oid=to_regprocedure(signature))); rollback;
